/**
 * The pill groups the explorer pages compose (a .explorer-pills track of
 * aria-pressed buttons, each value the choice it makes): the preview size
 * switch, the sort and category pills, the preview's viewport pills.
 * Imported by path from the page modules under js/pages/themes/.
 */

/**
 * Wire one pill group: a press on a button hands its value to `onValue`, and
 * the returned `press` marks the button of a value, so the page decides when
 * the pressed state follows.
 * @param {HTMLElement} root - the pill track holding the button[value]s
 * @param {(value: string) => void} onValue - called with the value a press picks
 * @returns {(value: string) => void} press: sets aria-pressed on every button
 */
export function bindPills(root, onValue) {
  root.addEventListener('click', (event) => {
    const $option = event.target.closest('button[value]');

    if ($option) {
      onValue($option.value);
    }
  });

  return (value) => {
    for (const $option of root.querySelectorAll('button[value]')) {
      $option.setAttribute('aria-pressed', String($option.value === value));
    }
  };
}
